on conflict (code) do update set
  name = excluded.name,
  category = excluded.category,
  description = excluded.description,
  plan_min = excluded.plan_min,
  status = excluded.status,
  can_feed_knowledge = excluded.can_feed_knowledge,
  can_create_events = excluded.can_create_events,
  can_be_channel_provider = excluded.can_be_channel_provider,
  is_native_platform_service = excluded.is_native_platform_service;
